"""Ice-indentation patch load generated by a CZM contact solve and fed to a panel.

Why this module exists
----------------------
The JOUR-ICE-STRUCT panel benchmark (``papers/jour-ice-struct/code/
panel_patch_load.py``, result file ``data/panel_patch_load_results.json``) puts a
*uniform* pressure ``p_ref`` on a rectangular patch of ice-belt plating and
compares the two-way plate moment with the beam-strip idealisation.  The pressure
patch itself is an input there: it is neither solved for nor coupled to the
plate.  The ice--structure cohesive-zone capability of this library
(:mod:`tensorfem.cohesive`) can produce an interface traction distribution, but
nothing projected it onto a plate/shell load vector.

This module closes that gap with three pieces:

``czm_contact_patch``
    Solves the *local* ice--structure normal contact problem: given the ice edge
    relief ``s(x, y)`` (how far a point of the ice surface sits behind the
    leading point), the bilinear cohesive interface law and a target normal force
    ``F``, find the approach ``delta0`` such that ``integral p dA = F`` with
    ``p = max(0, -t_cohesive(g))`` capped by the cohesive peak traction (local
    crushing ceiling).  The opening is ``g = delta0 - s(x, y) - w(x, y)`` where
    ``w`` is the panel deflection -- that ``w`` is what makes the coupling
    two-way.

``patch_from_contact``
    Projects a contact pressure field (regular grid, arbitrary extent, possibly
    offset from the panel centre) onto the plate nodal load vector of a
    rectangular panel by *exact sub-cell overlap integration* of
    ``integral N_i(x, y) p(x, y) dA``.  The projected load therefore conserves
    the contact force to machine precision (asserted, not assumed).

``solve_rect_panel``
    Simply supported / clamped Q4 Mindlin plate on a rectangular domain
    ``[0, a] x [0, b]``, reusing ``plate.q4_mindlin_stiffness`` and
    ``plate_mindlin.element_center_moments`` unchanged (no new element code).

The bidirectional loop ``contact -> load -> plate -> deflection -> contact`` is
run by :func:`coupled_patch_solve`; :func:`nonuniformity_scan` runs it for
several contact configurations and reports the peak panel stress of the
non-uniform patch against a uniform patch of the *same total force and same
footprint*, plus the JOUR-ICE-STRUCT design-point calibration case.

Independent references (used by the tests)
------------------------------------------
* Timoshenko & Woinowsky-Krieger Table 8, SSSS square, uniform load, nu = 0.3:
  ``w_max D/(q a^4) = 0.00406``, ``M_max/(q a^2) = 0.0479``.
* Kirchhoff Navier double series for a rectangular SSSS plate under an
  *arbitrary* pressure field (:func:`navier_rect_moments`), whose Fourier
  coefficients are obtained by Gauss quadrature of the same contact field the
  finite-element load vector was built from.  Two independent discretisations of
  the same physics, so the comparison is a verification and not a tautology.

Declared model limits
---------------------
* Linear elastic, small deflection Mindlin plate; no plasticity, no buckling.
* The interface law is used only through its undamaged normal penalty branch;
  the peak traction acts as a crushing ceiling (perfectly plastic cap) and the
  mode-I softening branch is **not** activated in compression.  A compressive
  patch load does not drive mode-I damage, and letting it soften would remove
  load from the most heavily indented points, which is not the observed
  ice-indentation behaviour.  This is a declared deviation from a
  general-purpose CZM, not a claim that ice crushing is elastic.
* Ice-side elasticity is lumped into the interface penalty stiffness
  ``k_n = E_crush / h_layer``; no ice continuum is solved.
* The pressure field is piecewise bilinear on the contact grid; its interpolation
  error is exposed through a grid-refinement check, not hidden.
"""

from __future__ import annotations

import math
from dataclasses import dataclass, field
from typing import Callable

import torch

from .cohesive import BilinearCohesiveLaw
from .foundation_plate_bending import (
    assemble_plate_foundation_system,
    solve_assembled_system,
    uniform_rect_mesh,
)
from .plate import _shape
from .plate_uniform_load import element_center_moments

__all__ = [
    "ContactPatch",
    "PanelSolution",
    "structured_panel_mesh",
    "solve_rect_panel",
    "patch_from_contact",
    "czm_contact_patch",
    "coupled_patch_solve",
    "deflection_at",
    "uniform_patch_pressure",
    "navier_rect_moments",
    "gauss_legendre",
    "nonuniformity_scan",
    "design_point_calibration",
    "_solve_with_patch",
    "default_law",
    "default_configurations",
    "DESIGN_POINT",
]

#: JOUR-ICE-STRUCT panel benchmark design point (identical to
#: ``panel_patch_load_results.json["design_point"]``): plate field 0.8 m x 0.7 m,
#: t = 22 mm, E = 206 GPa, nu = 0.3, reference local pressure 1 MPa.
DESIGN_POINT = {
    "l": 0.8,
    "s": 0.7,
    "t": 0.022,
    "E": 206.0e9,
    "nu": 0.3,
    "ReH": 355.0e6,
    "p_ref": 1.0e6,
    "A_ref": 1.0,
}

_G2 = 1.0 / math.sqrt(3.0)
_GAUSS2 = ((-_G2, 1.0), (_G2, 1.0))  # 2x2 Gauss: exact for bilinear x bilinear


# --------------------------------------------------------------------------
# mesh + boundary conditions (rectangular domain)
# --------------------------------------------------------------------------
def structured_panel_mesh(
    nx: int, ny: int, a: float, b: float, *, dtype=torch.float64
) -> tuple[torch.Tensor, torch.Tensor]:
    """Structured Q4 mesh on ``[0, a] x [0, b]`` with ``nx x ny`` elements."""
    if nx < 1 or ny < 1:
        raise ValueError("nx and ny must be positive")
    if a <= 0.0 or b <= 0.0:
        raise ValueError("panel sides must be positive")
    x = torch.linspace(0.0, a, nx + 1, dtype=dtype)
    y = torch.linspace(0.0, b, ny + 1, dtype=dtype)
    xx, yy = torch.meshgrid(x, y, indexing="xy")
    nodes = torch.stack((xx.reshape(-1), yy.reshape(-1)), dim=1)
    elements = []
    for j in range(ny):
        for i in range(nx):
            n0 = j * (nx + 1) + i
            elements.append((n0, n0 + 1, n0 + nx + 2, n0 + nx + 1))
    return nodes, torch.tensor(elements, dtype=torch.long)


def _panel_bcs(
    nodes: torch.Tensor, a: float, b: float, ndof: int, boundary: str
) -> tuple[torch.Tensor, torch.Tensor]:
    """``(fixed, free)`` dofs; the hard simple-support convention of
    ``plate_mindlin._apply_boundary_conditions``, extended to a rectangle."""
    tol_x, tol_y = a * 1e-12, b * 1e-12
    xedge = (nodes[:, 0].abs() < tol_x) | ((nodes[:, 0] - a).abs() < tol_x)
    yedge = (nodes[:, 1].abs() < tol_y) | ((nodes[:, 1] - b).abs() < tol_y)
    edge = xedge | yedge
    w_dofs = 3 * torch.nonzero(edge, as_tuple=False).flatten()
    if boundary == "simply_supported":
        tx_dofs = 3 * torch.nonzero(yedge, as_tuple=False).flatten() + 1
        ty_dofs = 3 * torch.nonzero(xedge, as_tuple=False).flatten() + 2
        fixed = torch.cat((w_dofs, tx_dofs, ty_dofs)).unique()
    elif boundary == "clamped":
        rot = 3 * torch.nonzero(edge, as_tuple=False).flatten()
        fixed = torch.cat((w_dofs, rot + 1, rot + 2)).unique()
    else:
        raise ValueError("boundary must be 'simply_supported' or 'clamped'")
    all_dofs = torch.arange(ndof)
    free = all_dofs[~torch.isin(all_dofs, fixed)]
    return fixed, free


# --------------------------------------------------------------------------
# contact pressure field on a regular grid (piecewise bilinear)
# --------------------------------------------------------------------------
@dataclass(frozen=True)
class ContactPatch:
    """A solved (or prescribed) ice--structure normal-pressure patch.

    ``pressure`` has shape ``(len(x), len(y))``; ``opening`` matches it.
    """

    x: torch.Tensor
    y: torch.Tensor
    pressure: torch.Tensor
    total_force: float
    contact_area: float
    peak_pressure: float
    centroid: tuple[float, float]
    approach: float
    opening: torch.Tensor
    residual: float
    config: dict = field(default_factory=dict)

    def as_dict(self) -> dict:
        mean = self.total_force / self.contact_area if self.contact_area > 0.0 else 0.0
        return {
            "config": self.config,
            "total_force_N": self.total_force,
            "contact_area_m2": self.contact_area,
            "peak_pressure_MPa": self.peak_pressure / 1e6,
            "mean_pressure_over_contact_MPa": mean / 1e6,
            "pressure_peak_over_mean": (self.peak_pressure / mean) if mean > 0.0 else 1.0,
            "centroid_m": list(self.centroid),
            "approach_m": self.approach,
            "force_residual": self.residual,
        }

    def pressure_at(self, xq: torch.Tensor, yq: torch.Tensor) -> torch.Tensor:
        """Bilinear interpolation of the pressure field, zero outside the grid."""
        x, y, p = self.x, self.y, self.pressure
        nxn, nyn = x.numel(), y.numel()
        xq = torch.as_tensor(xq, dtype=x.dtype)
        yq = torch.as_tensor(yq, dtype=y.dtype)
        ix = torch.searchsorted(x, xq, right=True) - 1
        iy = torch.searchsorted(y, yq, right=True) - 1
        inside = (ix >= 0) & (ix < nxn - 1) & (iy >= 0) & (iy < nyn - 1)
        ix = ix.clamp(0, nxn - 2)
        iy = iy.clamp(0, nyn - 2)
        tx = ((xq - x[ix]) / (x[ix + 1] - x[ix])).clamp(0.0, 1.0)
        ty = ((yq - y[iy]) / (y[iy + 1] - y[iy])).clamp(0.0, 1.0)
        val = (
            p[ix, iy] * (1 - tx) * (1 - ty)
            + p[ix + 1, iy] * tx * (1 - ty)
            + p[ix, iy + 1] * (1 - tx) * ty
            + p[ix + 1, iy + 1] * tx * ty
        )
        return torch.where(inside, val, torch.zeros_like(val))


# --------------------------------------------------------------------------
# exact conservative projection onto the panel nodal load vector
# --------------------------------------------------------------------------
def _axis_breaks(lo: float, hi: float, grid: torch.Tensor) -> list[float]:
    """Interval ``[lo, hi]`` split at every grid node that falls inside it."""
    inner = [float(v) for v in grid.detach().cpu().tolist() if lo < float(v) < hi]
    return [lo] + inner + [hi]


def patch_from_contact(
    patch: ContactPatch,
    nx: int,
    ny: int,
    a: float,
    b: float,
    *,
    dtype=torch.float64,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, dict]:
    """Project a contact pressure field onto the panel nodal load vector.

    ``integral N_i(x, y) p(x, y) dA`` is integrated *exactly*: every panel element
    is split at the contact-grid lines it crosses, and on each sub-rectangle
    ``N_i`` and ``p`` are both bilinear, so the 2x2 Gauss rule is exact.  The
    projected nodal loads therefore sum to the contact force to machine
    precision.

    Returns ``(nodes, elements, f, info)`` with ``f`` of length ``3*n_nodes``
    (only ``w`` dofs nonzero) and ``info`` carrying the force-balance audit.
    """
    nodes, elements = structured_panel_mesh(nx, ny, a, b, dtype=dtype)
    ndof = 3 * nodes.shape[0]
    f = torch.zeros(ndof, dtype=dtype)

    xg, yg = patch.x, patch.y
    x_lo = max(0.0, min(float(xg[0]), a))
    x_hi = min(a, max(float(xg[-1]), 0.0))
    y_lo = max(0.0, min(float(yg[0]), b))
    y_hi = min(b, max(float(yg[-1]), 0.0))
    loaded_area = 0.0

    if x_hi <= x_lo or y_hi <= y_lo:
        return nodes, elements, f, {
            "projected_force": 0.0,
            "contact_force": patch.total_force,
            "force_error_rel": 1.0 if patch.total_force > 0.0 else 0.0,
            "loaded_area": 0.0,
        }

    xs_mesh = torch.linspace(0.0, a, nx + 1, dtype=dtype)
    ys_mesh = torch.linspace(0.0, b, ny + 1, dtype=dtype)
    for e, conn in enumerate(elements):
        jy, ix = divmod(e, nx)
        exa, exb = float(xs_mesh[ix]), float(xs_mesh[ix + 1])
        eya, eyb = float(ys_mesh[jy]), float(ys_mesh[jy + 1])
        xa, xb = max(exa, x_lo), min(exb, x_hi)
        ya, yb = max(eya, y_lo), min(eyb, y_hi)
        if xb <= xa or yb <= ya:
            continue
        fe = torch.zeros(12, dtype=dtype)
        for sx0, sx1 in zip(_axis_breaks(xa, xb, xg)[:-1], _axis_breaks(xa, xb, xg)[1:]):
            for sy0, sy1 in zip(
                _axis_breaks(ya, yb, yg)[:-1], _axis_breaks(ya, yb, yg)[1:]
            ):
                hx, hy = sx1 - sx0, sy1 - sy0
                for gx, wx in _GAUSS2:
                    xp = 0.5 * (sx0 + sx1) + 0.5 * hx * gx
                    xi = 2.0 * (xp - exa) / (exb - exa) - 1.0
                    for gy, wy in _GAUSS2:
                        yp = 0.5 * (sy0 + sy1) + 0.5 * hy * gy
                        eta = 2.0 * (yp - eya) / (eyb - eya) - 1.0
                        N, _ = _shape(
                            torch.tensor(xi, dtype=dtype),
                            torch.tensor(eta, dtype=dtype),
                        )
                        pq = float(
                            patch.pressure_at(
                                torch.tensor([xp], dtype=dtype),
                                torch.tensor([yp], dtype=dtype),
                            )[0]
                        )
                        w = wx * wy * 0.25 * hx * hy
                        for i in range(4):
                            fe[3 * i] += N[i] * pq * w
                loaded_area += hx * hy
        dofs = torch.stack((3 * conn, 3 * conn + 1, 3 * conn + 2), dim=1).reshape(-1)
        f[dofs] += fe

    projected = float(f.reshape(-1, 3)[:, 0].sum())
    err = abs(projected - patch.total_force) / max(abs(patch.total_force), 1e-30)
    return nodes, elements, f, {
        "projected_force": projected,
        "contact_force": patch.total_force,
        "force_error_rel": err,
        "loaded_area": loaded_area,
    }


# --------------------------------------------------------------------------
# rectangular Mindlin panel solve (reuses the merged element)
# --------------------------------------------------------------------------
@dataclass(frozen=True)
class PanelSolution:
    """Mindlin panel solution (duck-types ``MindlinPlateResult``)."""

    displacement: torch.Tensor
    nodes: torch.Tensor
    elements: torch.Tensor
    young: float
    poisson: float
    thickness: float
    boundary: str
    side_a: float
    side_b: float
    nx: int
    ny: int
    load_info: dict = field(default_factory=dict)

    def moments(self) -> dict:
        """``(Mx, My, Mxy)`` at element centres through the merged recovery routine."""
        return element_center_moments(self)

    def _fields(self) -> dict:
        mom = self.moments()
        mx = torch.tensor(mom["moment_x"], dtype=torch.float64)
        my = torch.tensor(mom["moment_y"], dtype=torch.float64)
        mxy = torch.tensor(mom["moment_xy"], dtype=torch.float64)
        mom["sigma_vm"] = (
            6.0
            * torch.sqrt((mx**2 - mx * my + my**2 + 3.0 * mxy**2).clamp_min(0.0))
            / self.thickness**2
        )
        mom["sigma_Mx"] = 6.0 * mx.abs() / self.thickness**2
        return mom

    def stress_at(self, x: float, y: float) -> dict:
        """Bending stresses at the element centre nearest ``(x, y)``.

        This is the sampling convention of the JOUR-ICE-STRUCT panel benchmark
        (values are read at the patch centre, never on a supported edge).
        """
        mom = self._fields()
        cx = torch.tensor(mom["x"], dtype=torch.float64)
        cy = torch.tensor(mom["y"], dtype=torch.float64)
        i = int(torch.argmin((cx - x) ** 2 + (cy - y) ** 2))
        return {
            "sigma_vm_MPa": float(mom["sigma_vm"][i]) / 1e6,
            "sigma_Mx_MPa": float(mom["sigma_Mx"][i]) / 1e6,
            "moment_x_Nm_per_m": float(mom["moment_x"][i]),
            "moment_y_Nm_per_m": float(mom["moment_y"][i]),
            "moment_xy_Nm_per_m": float(mom["moment_xy"][i]),
            "at_m": [mom["x"][i], mom["y"][i]],
        }

    def peak_stress(self, interior_margin: int = 1) -> dict:
        """Peak plate bending stresses over the *interior* element centres.

        ``sigma_vm = 6*sqrt(Mx^2 - Mx My + My^2 + 3 Mxy^2)/t^2`` and
        ``sigma_Mx = 6|Mx|/t^2`` (the JOUR-ICE-STRUCT definitions).  ``Mxy``
        carries a spurious boundary layer at the simply supported edges of a Q4
        Mindlin mesh, so by default the outer ``interior_margin`` ring of
        elements is excluded from the peak search; the value at the patch centre
        is available from :meth:`stress_at` and is unaffected by the choice.
        """
        mom = self._fields()
        cx = torch.tensor(mom["x"], dtype=torch.float64)
        cy = torch.tensor(mom["y"], dtype=torch.float64)
        dx = self.side_a / self.nx
        dy = self.side_b / self.ny
        keep = (
            (cx > interior_margin * dx)
            & (cx < self.side_a - interior_margin * dx)
            & (cy > interior_margin * dy)
            & (cy < self.side_b - interior_margin * dy)
        )
        if not bool(keep.any()):  # pragma: no cover - defensive
            keep = torch.ones_like(cx, dtype=torch.bool)
        sv = mom["sigma_vm"].masked_select(keep)
        sm = mom["sigma_Mx"].masked_select(keep)
        iv = int(torch.argmax(sv))
        im = int(torch.argmax(sm))
        xs = cx.masked_select(keep)
        ys = cy.masked_select(keep)
        return {
            "sigma_vm_MPa": float(sv[iv]) / 1e6,
            "sigma_Mx_MPa": float(sm[im]) / 1e6,
            "peak_sigma_vm_at_m": [float(xs[iv]), float(ys[iv])],
            "peak_sigma_Mx_at_m": [float(xs[im]), float(ys[im])],
            "interior_margin_elements": interior_margin,
        }


def solve_rect_panel(
    nx: int,
    ny: int,
    a: float,
    b: float,
    *,
    young: float,
    poisson: float,
    thickness: float,
    load: torch.Tensor | float,
    boundary: str = "simply_supported",
    shear_treatment: str = "mitc",
    dtype=torch.float64,
) -> PanelSolution:
    """Q4 Mindlin plate on ``[0, a] x [0, b]`` through the merged batched path.

    The mesh, the vectorised element stiffness and the sparse solve are the
    merged :mod:`tensorfem.foundation_plate_bending` routines (``uniform_rect_mesh``,
    ``assemble_plate_foundation_system``, ``solve_assembled_system``) -- no element
    or assembly code is duplicated here.  ``load`` is either a nodal load vector
    of length ``3*n_nodes`` (as returned by :func:`patch_from_contact`) or a
    uniform pressure in Pa; that is all the patch problem needs.
    """
    nodes, elements = uniform_rect_mesh(nx, ny, a, b, dtype=dtype)
    n_nodes = nodes.shape[0]
    ndof = 3 * n_nodes
    if isinstance(load, torch.Tensor):
        if load.numel() != ndof:
            raise ValueError(f"nodal load vector must have {ndof} entries")
        system = assemble_plate_foundation_system(
            nodes,
            elements,
            young=young,
            poisson=poisson,
            thickness=thickness,
            pressure=0.0,
            shear_treatment=shear_treatment,
        )
        rows, cols, vals, force, ndof = system
        force = force + load.to(dtype=torch.float64)
        info = {"kind": "nodal", "total_force": float(load.reshape(-1, 3)[:, 0].sum())}
    else:
        pressure = float(load)
        system = assemble_plate_foundation_system(
            nodes,
            elements,
            young=young,
            poisson=poisson,
            thickness=thickness,
            pressure=pressure,
            shear_treatment=shear_treatment,
        )
        rows, cols, vals, force, ndof = system
        info = {"kind": "pressure", "total_force": float(force.reshape(-1, 3)[:, 0].sum())}

    fixed, _ = _panel_bcs(nodes, a, b, ndof, boundary)
    u = solve_assembled_system((rows, cols, vals, force, ndof), fixed)
    return PanelSolution(
        displacement=u,
        nodes=nodes,
        elements=elements,
        young=young,
        poisson=poisson,
        thickness=thickness,
        boundary=boundary,
        side_a=a,
        side_b=b,
        nx=nx,
        ny=ny,
        load_info=info,
    )


def deflection_at(sol: PanelSolution, xq: torch.Tensor, yq: torch.Tensor) -> torch.Tensor:
    """Bilinear interpolation of the panel deflection (positive = load direction)."""
    xnodes = torch.unique(sol.nodes[:, 0])
    ynodes = torch.unique(sol.nodes[:, 1])
    nxn, nyn = xnodes.numel(), ynodes.numel()
    w = sol.displacement.reshape(-1, 3)[:, 0].reshape(nyn, nxn)
    xq = torch.as_tensor(xq, dtype=xnodes.dtype)
    yq = torch.as_tensor(yq, dtype=ynodes.dtype)
    ix = (torch.searchsorted(xnodes, xq, right=True) - 1).clamp(0, nxn - 2)
    iy = (torch.searchsorted(ynodes, yq, right=True) - 1).clamp(0, nyn - 2)
    tx = ((xq - xnodes[ix]) / (xnodes[ix + 1] - xnodes[ix])).clamp(0.0, 1.0)
    ty = ((yq - ynodes[iy]) / (ynodes[iy + 1] - ynodes[iy])).clamp(0.0, 1.0)
    return (
        w[iy, ix] * (1 - tx) * (1 - ty)
        + w[iy, ix + 1] * tx * (1 - ty)
        + w[iy + 1, ix] * (1 - tx) * ty
        + w[iy + 1, ix + 1] * tx * ty
    )

# --------------------------------------------------------------------------
# CZM contact solve
# --------------------------------------------------------------------------
def _edge_relief(
    xg: torch.Tensor, yg: torch.Tensor, edge: dict, centre: tuple[float, float]
) -> torch.Tensor:
    """Ice-edge relief ``s(x, y)`` [m]: depth of a point behind the leading point."""
    kind = edge.get("kind", "flat")
    amp = float(edge.get("amplitude", 0.0))
    X, Y = torch.meshgrid(xg - centre[0], yg - centre[1], indexing="ij")
    if kind == "flat":
        return torch.zeros_like(X)
    if kind == "spherical":
        R = float(edge["radius"])
        return amp * torch.clamp((X**2 + Y**2) / R**2, max=1.0)
    if kind == "cylindrical":
        R = float(edge["radius"])
        return amp * torch.clamp(Y**2 / R**2, max=1.0)
    raise ValueError(f"unknown ice-edge kind {kind!r}")


def _pressure_from_opening(
    g: torch.Tensor, law: BilinearCohesiveLaw, ceiling: float
) -> torch.Tensor:
    """Normal contact pressure from the local opening ``g`` (``> 0`` = penetration).

    The cohesive law's undamaged *compressive* branch (negative separation, which
    the law documents as the undamaged penalty) is evaluated directly; the result
    is capped by the cohesive peak traction, used here as the local crushing
    ceiling (perfectly plastic cap).  No mode-I softening is activated in
    compression -- see the module docstring.
    """
    separation = -g.clamp_min(0.0)
    resp = law.update(separation)
    p = (-resp.traction).clamp_min(0.0)
    return torch.minimum(p, torch.full_like(p, float(ceiling)))


def czm_contact_patch(
    *,
    law: BilinearCohesiveLaw,
    ceiling: float,
    edge: dict,
    total_force: float,
    panel: tuple[float, float] = (DESIGN_POINT["l"], DESIGN_POINT["s"]),
    centre: tuple[float, float] | None = None,
    grid: int = 97,
    deflection: torch.Tensor | None = None,
    contact_box: tuple[float, float, float, float] | None = None,
    tol: float = 1e-12,
    max_iter: int = 200,
) -> ContactPatch:
    """Solve the local ice--structure CZM contact for a prescribed normal force.

    Unknown: the rigid approach ``delta0``.  Opening field
    ``g = delta0 - s(x, y) - w(x, y)``, ``w`` being the panel deflection sampled
    on the same contact grid (flat array of length ``grid*grid``).  A bisection on
    ``delta0`` enforces ``integral p dA = total_force``.

    Parameters
    ----------
    law : BilinearCohesiveLaw
        Interface law; its penalty stiffness sets the pressure--penetration slope
        and its peak traction bounds the pressure.
    ceiling : float
        Local crushing ceiling [Pa]; values above ``law.peak_traction`` are
        meaningless because the law cannot deliver more traction.
    edge : dict
        Ice edge relief ``{"kind": "flat"|"spherical"|"cylindrical", "radius": m,
        "amplitude": m, "box_half": m}``.
    total_force : float
        Target normal force [N].
    deflection : torch.Tensor, optional
        Panel deflection on the contact grid, positive in the load direction.
    """
    if total_force <= 0.0:
        raise ValueError("total_force must be positive")
    a, b = panel
    cx, cy = (a / 2.0, b / 2.0) if centre is None else centre
    half = float(edge.get("box_half", 2.0 * float(edge.get("amplitude", 0.0)) + 0.05))
    if contact_box is None:
        contact_box = (cx - half, cx + half, cy - half, cy + half)
    x0, x1, y0, y1 = contact_box
    xg = torch.linspace(x0, x1, grid, dtype=torch.float64)
    yg = torch.linspace(y0, y1, grid, dtype=torch.float64)
    dx = float(xg[1] - xg[0])
    dy = float(yg[1] - yg[0])

    dX, dY = torch.meshgrid(xg, yg, indexing="ij")
    wx = torch.full((grid,), dx, dtype=torch.float64)
    wx[0] = wx[-1] = 0.5 * dx
    wy = torch.full((grid,), dy, dtype=torch.float64)
    wy[0] = wy[-1] = 0.5 * dy
    AW = wx[:, None] * wy[None, :]

    s = _edge_relief(xg, yg, edge, (cx, cy))
    w = (
        torch.zeros_like(s)
        if deflection is None
        else deflection.to(torch.float64).reshape(grid, grid)
    )
    base = -s - w  # g = delta0 + base

    def force_of(delta0: float) -> tuple[torch.Tensor, torch.Tensor, float]:
        g = delta0 + base
        p = _pressure_from_opening(g, law, ceiling)
        return p, g, float((p * AW).sum())

    lo = float(base.min()) - 1.0
    hi = float(-base.min()) + 1.0
    step = max(1e-9, 0.1 * (hi - lo))
    while force_of(lo)[2] > 0.0:  # `lo` must be a no-contact state
        lo -= step
        step *= 2.0
    f_hi = force_of(hi)[2]
    step = max(1e-9, 0.1 * (hi - lo))
    while f_hi < total_force:
        hi += step
        step *= 2.0
        f_hi = force_of(hi)[2]
    for _ in range(max_iter):
        mid = 0.5 * (lo + hi)
        if force_of(mid)[2] < total_force:
            lo = mid
        else:
            hi = mid
        if (hi - lo) <= tol * max(1.0, abs(mid)):
            break
    delta0 = 0.5 * (lo + hi)
    p, g, f_tot = force_of(delta0)
    contact = (g > 0.0).to(torch.float64)
    area = float((AW * contact).sum())
    resid = abs(f_tot - total_force) / total_force
    cxs = float((p * AW * dX).sum() / f_tot)
    cys = float((p * AW * dY).sum() / f_tot)
    return ContactPatch(
        x=xg,
        y=yg,
        pressure=p,
        total_force=f_tot,
        contact_area=area,
        peak_pressure=float(p.max()),
        centroid=(cxs, cys),
        approach=delta0,
        opening=g,
        residual=resid,
        config={
            "edge": dict(edge),
            "ceiling_MPa": ceiling / 1e6,
            "target_force_N": total_force,
            "grid": grid,
            "contact_box": [float(v) for v in contact_box],
            "centre": [cx, cy],
            "stiffness_Pa_per_m": float(getattr(law, "stiffness", 0.0)),
            "peak_traction_MPa": float(getattr(law, "peak_traction", 0.0)) / 1e6,
            "coupled_to_plate_deflection": deflection is not None,
        },
    )


# --------------------------------------------------------------------------
# bidirectionally coupled solve
# --------------------------------------------------------------------------
def coupled_patch_solve(
    *,
    nx: int,
    ny: int,
    panel: tuple[float, float] = (DESIGN_POINT["l"], DESIGN_POINT["s"]),
    thickness: float = DESIGN_POINT["t"],
    young: float = DESIGN_POINT["E"],
    poisson: float = DESIGN_POINT["nu"],
    law: BilinearCohesiveLaw,
    ceiling: float,
    edge: dict,
    total_force: float,
    centre: tuple[float, float] | None = None,
    grid: int = 97,
    boundary: str = "simply_supported",
    relax: float = 0.5,
    tol: float = 1e-4,
    max_coupling: int = 12,
) -> tuple[ContactPatch, PanelSolution, dict]:
    """Run ``contact -> patch load -> plate -> deflection -> contact`` to a fixed point.

    Convergence criterion: relative change of the pressure field between sweeps,
    ``max|p_k - p_{k-1}| / max(p_k)``, below ``tol``.  Each sweep re-solves the
    approach, so the total normal force is held at every iteration.
    """
    a, b = panel
    cx, cy = (a / 2.0, b / 2.0) if centre is None else centre
    half = float(edge.get("box_half", 2.0 * float(edge.get("amplitude", 0.0)) + 0.05))
    x0, x1, y0, y1 = cx - half, cx + half, cy - half, cy + half
    xg = torch.linspace(x0, x1, grid, dtype=torch.float64)
    yg = torch.linspace(y0, y1, grid, dtype=torch.float64)
    XQ, YQ = torch.meshgrid(xg, yg, indexing="ij")
    XF, YF = XQ.reshape(-1), YQ.reshape(-1)

    w_hat = torch.zeros(grid, grid, dtype=torch.float64)
    history: list[dict] = []
    patch: ContactPatch | None = None
    sol: PanelSolution | None = None
    prev_p: torch.Tensor | None = None
    for k in range(max_coupling):
        patch = czm_contact_patch(
            law=law,
            ceiling=ceiling,
            edge=edge,
            total_force=total_force,
            panel=panel,
            centre=(cx, cy),
            grid=grid,
            deflection=w_hat,
            contact_box=(x0, x1, y0, y1),
        )
        _, _, f, info = patch_from_contact(patch, nx, ny, a, b)
        sol = solve_rect_panel(
            nx,
            ny,
            a,
            b,
            young=young,
            poisson=poisson,
            thickness=thickness,
            load=f,
            boundary=boundary,
        )
        # the plate moving with the load at the contact point reduces the opening
        w_new = deflection_at(sol, XF, YF).reshape(grid, grid)
        dp = (
            float((patch.pressure - prev_p).abs().max() / max(patch.peak_pressure, 1e-30))
            if prev_p is not None
            else float("nan")
        )
        history.append(
            {
                "sweep": k,
                "approach_m": patch.approach,
                "peak_pressure_MPa": patch.peak_pressure / 1e6,
                "contact_area_m2": patch.contact_area,
                "force_projection_error_rel": info["force_error_rel"],
                "plate_centre_deflection_mm": float(
                    deflection_at(
                        sol,
                        torch.tensor([a / 2.0], dtype=torch.float64),
                        torch.tensor([b / 2.0], dtype=torch.float64),
                    )[0]
                )
                * 1e3,
                "pressure_change_rel": dp,
            }
        )
        w_hat = (1.0 - relax) * w_hat + relax * w_new
        prev_p = patch.pressure.clone()
        if dp < tol:
            break
    assert patch is not None and sol is not None
    return patch, sol, {
        "sweeps": len(history),
        "converged": bool(history[-1]["pressure_change_rel"] < tol),
        "tol": tol,
        "history": history,
    }


# --------------------------------------------------------------------------
# independent reference: Kirchhoff Navier series on a rectangle
# --------------------------------------------------------------------------
def gauss_legendre(n: int) -> tuple[list[float], list[float]]:
    """Gauss-Legendre nodes/weights on ``[-1, 1]`` (``1 <= n <= 6``)."""
    if n < 1 or n > 6:
        raise ValueError("n must be in 1..6")
    nodes, weights = [], []
    for i in range(1, n + 1):
        z = math.cos(math.pi * (i - 0.25) / (n + 0.5))
        dp = 1.0
        for _ in range(100):
            p0, p1 = 1.0, 0.0
            for j in range(1, n + 1):
                p2, p1 = p1, p0
                p0 = ((2 * j - 1) * z * p1 - (j - 1) * p2) / j
            dp = n * (z * p0 - p1) / (z * z - 1.0)
            dz = -p0 / dp
            z += dz
            if abs(dz) < 1e-16:
                break
        nodes.append(z)
        weights.append(2.0 / ((1.0 - z * z) * dp * dp))
    return nodes, weights


def navier_rect_moments(
    patch: ContactPatch,
    a: float,
    b: float,
    *,
    young: float,
    poisson: float,
    thickness: float,
    x: float,
    y: float,
    terms: int = 121,
    nq: int = 4,
) -> dict:
    """Kirchhoff Navier series for a rectangular SSSS plate under ``patch``.

    Independent of the finite-element path: the load Fourier coefficients come
    from ``nq x nq`` Gauss quadrature of the *same* bilinear pressure field, and
    the series is summed to ``terms`` half-waves each way.  Returns ``moment_x``,
    ``moment_y``, ``moment_xy`` [N m/m] and the force the quadrature integrates.
    """
    D = young * thickness**3 / (12.0 * (1.0 - poisson**2))
    xg, yg = patch.x, patch.y
    gn, gw = gauss_legendre(nq)
    xs: list[float] = []
    ys: list[float] = []
    ws: list[float] = []
    for i in range(xg.numel() - 1):
        hx = float(xg[i + 1] - xg[i])
        for j in range(yg.numel() - 1):
            hy = float(yg[j + 1] - yg[j])
            for ax, wx in zip(gn, gw):
                for ay, wy in zip(gn, gw):
                    xs.append(float(xg[i]) + 0.5 * hx * (1.0 + ax))
                    ys.append(float(yg[j]) + 0.5 * hy * (1.0 + ay))
                    ws.append(0.25 * wx * wy * hx * hy)
    xq = torch.tensor(xs, dtype=torch.float64)
    yq = torch.tensor(ys, dtype=torch.float64)
    wq = torch.tensor(ws, dtype=torch.float64)
    pq = patch.pressure_at(xq, yq)
    total = float((pq * wq).sum())

    m = torch.arange(1, terms + 1, dtype=torch.float64)
    km = m * math.pi / a
    ln = m * math.pi / b
    Sx = torch.sin(torch.outer(xq, km))
    Sy = torch.sin(torch.outer(yq, ln))
    Q = (4.0 / (a * b)) * (Sx * (pq * wq)[:, None]).T @ Sy  # q_mn
    K2 = km[:, None] ** 2 + ln[None, :] ** 2
    W = Q / (D * K2**2)
    sx = torch.sin(km * x)
    sy = torch.sin(ln * y)
    cx = torch.cos(km * x)
    cy = torch.cos(ln * y)
    SS = torch.outer(sx, sy)
    mx = float(D * torch.sum(W * (km[:, None] ** 2 + poisson * ln[None, :] ** 2) * SS))
    my = float(D * torch.sum(W * (ln[None, :] ** 2 + poisson * km[:, None] ** 2) * SS))
    mxy = float(
        -D * (1.0 - poisson) * torch.sum(W * (km[:, None] * ln[None, :]) * torch.outer(cx, cy))
    )
    return {
        "moment_x": mx,
        "moment_y": my,
        "moment_xy": mxy,
        "total_force": total,
        "bending_stiffness": D,
        "terms": terms,
    }


def uniform_patch_pressure(
    *,
    total_force: float,
    centre: tuple[float, float],
    half_x: float,
    half_y: float,
    panel: tuple[float, float],
    grid: int = 97,
) -> ContactPatch:
    """Uniform reference patch carrying the same total force as a solved patch.

    The pressure is constant over ``2*half_x x 2*half_y`` and zero elsewhere --
    exactly the idealisation of the JOUR-ICE-STRUCT panel benchmark, so the
    ``non-uniform vs uniform`` comparison is at the same caliber.
    """
    a, b = panel
    area = 4.0 * half_x * half_y
    p0 = total_force / area
    x0, x1 = centre[0] - half_x, centre[0] + half_x
    y0, y1 = centre[1] - half_y, centre[1] + half_y
    def _grid(lo: float, hi: float, e0: float, e1: float) -> torch.Tensor:
        base = torch.linspace(lo, hi, grid, dtype=torch.float64).tolist()
        pts = sorted(set(base + [float(e0), float(e1)]))
        return torch.tensor(pts, dtype=torch.float64)

    xg = _grid(min(0.0, x0), max(a, x1), x0, x1)
    yg = _grid(min(0.0, y0), max(b, y1), y0, y1)
    X, Y = torch.meshgrid(xg, yg, indexing="ij")
    p = torch.where(
        (X >= x0) & (X <= x1) & (Y >= y0) & (Y <= y1),
        torch.full_like(X, p0),
        torch.zeros_like(X),
    )
    def _trap(g: torch.Tensor) -> torch.Tensor:
        d = torch.diff(g)
        w = torch.zeros(g.numel(), dtype=torch.float64)
        w[:-1] += 0.5 * d
        w[1:] += 0.5 * d
        return w

    return ContactPatch(
        x=xg,
        y=yg,
        pressure=p,
        total_force=float((p * (_trap(xg)[:, None] * _trap(yg)[None, :])).sum()),
        contact_area=area,
        peak_pressure=p0,
        centroid=(0.5 * (x0 + x1), 0.5 * (y0 + y1)),
        approach=0.0,
        opening=torch.zeros_like(p),
        residual=0.0,
        config={
            "kind": "uniform_reference",
            "pressure_MPa": p0 / 1e6,
            "footprint_m": [2.0 * half_x, 2.0 * half_y],
        },
    )


# --------------------------------------------------------------------------
# scan definitions + design-point calibration
# --------------------------------------------------------------------------
def default_law() -> BilinearCohesiveLaw:
    """Interface law used by the scan.

    ``k_n = E_crush / h_layer = 120 MPa / 0.03 m = 4e9 Pa/m`` -- a compliant
    crushed-ice edge layer, not a rigid penalty; that is what makes the pressure
    field smooth instead of a binary contact mask.  ``sigma_c = 2 MPa`` is the
    local crushing ceiling (twice the 1 MPa panel design pressure) and
    ``G_Ic = 20 J/m^2`` only sets the mode-I opening (unused in compression).
    """
    return BilinearCohesiveLaw(stiffness=4.0e9, peak_traction=2.0e6, fracture_energy=1200.0)


def default_configurations() -> list[dict]:
    """Contact configurations swept by :func:`nonuniformity_scan`.

    The pressure non-uniformity comes from three physically distinct sources: ice
    edge relief (spherical vs cylindrical), eccentricity, and a stress-limited
    (capped) patch.  ``C1`` is the limit case that must collapse onto the uniform
    patch, which is what makes the scan self-checking.
    """
    return [
        {
            "name": "C1-flat-edge-oneway",
            "edge": {"kind": "flat", "amplitude": 0.0, "box_half": 0.10},
            "coupled": False,
            "note": "flat edge, one-way (w=0): limit case, must reproduce a uniform patch",
        },
        {
            "name": "C2-spherical-oneway",
            "edge": {"kind": "spherical", "radius": 1.0, "amplitude": 0.02, "box_half": 0.10},
            "coupled": False,
            "note": "spherical edge, one-way: pressure bell from edge relief, capped at sigma_c",
        },
        {
            "name": "C3-spherical-twoway",
            "edge": {"kind": "spherical", "radius": 1.0, "amplitude": 0.02, "box_half": 0.10},
            "coupled": True,
            "note": "same edge, two-way: panel deflection feeds back into the opening",
        },
        {
            "name": "C4-cylindrical-twoway-eccentric",
            "edge": {"kind": "cylindrical", "radius": 0.6, "amplitude": 0.03, "box_half": 0.12},
            "coupled": True,
            "offset": (0.12, 0.0),
            "note": "transverse ridge off the panel centre: edge stress concentration",
        },
    ]


def _solve_with_patch(
    patch: ContactPatch,
    *,
    nx: int,
    ny: int,
    panel: tuple[float, float],
    thickness: float,
    young: float,
    poisson: float,
    boundary: str = "simply_supported",
) -> tuple[PanelSolution, dict]:
    _, _, f, info = patch_from_contact(patch, nx, ny, panel[0], panel[1])
    sol = solve_rect_panel(
        nx,
        ny,
        panel[0],
        panel[1],
        young=young,
        poisson=poisson,
        thickness=thickness,
        load=f,
        boundary=boundary,
    )
    return sol, info


def design_point_calibration(
    *,
    nx: int = 40,
    ny: int = 35,
    young: float = DESIGN_POINT["E"],
    poisson: float = DESIGN_POINT["nu"],
    thickness: float = DESIGN_POINT["t"],
    panel: tuple[float, float] = (DESIGN_POINT["l"], DESIGN_POINT["s"]),
    p_ref: float = DESIGN_POINT["p_ref"],
    lambda_c_over_l: float = 0.1,
) -> dict:
    """Reproduce the JOUR-ICE-STRUCT design-point patch case with this FEM path.

    Baseline (``panel_patch_load_results.json``, ``plate_vs_strip`` row
    ``lambda_c_over_l = 0.1``, ``patch_mode = full_breadth``, Kirchhoff Navier
    series): ``sigma_plate = 73.371 MPa``, ``sigma_plate_Mx = 78.668 MPa``.
    Also runs the Timoshenko Table 8 check (SSSS square, uniform load,
    ``M_max/(q a^2) = 0.0479``) because the baseline's own method was verified
    against it -- that is the accuracy caliber both results must share.
    """
    a, b = panel
    c = lambda_c_over_l * a
    # full-breadth patch centred on the panel: uniform p_ref over c x b
    patch = uniform_patch_pressure(
        total_force=p_ref * c * b,
        centre=(0.5 * a, 0.5 * b),
        half_x=0.5 * c,
        half_y=0.5 * b,
        panel=panel,
        grid=97,
    )
    sol, info = _solve_with_patch(
        patch,
        nx=nx,
        ny=ny,
        panel=panel,
        thickness=thickness,
        young=young,
        poisson=poisson,
    )
    peak = sol.stress_at(0.5 * a, 0.5 * b)
    nav = navier_rect_moments(
        patch,
        a,
        b,
        young=young,
        poisson=poisson,
        thickness=thickness,
        x=peak["at_m"][0],
        y=peak["at_m"][1],
        terms=121,
    )
    sig_navier_mx = 6.0 * abs(nav["moment_x"]) / thickness**2 / 1e6  # MPa
    sig_navier_vm = 6.0 * float(
        (nav["moment_x"] ** 2 - nav["moment_x"] * nav["moment_y"] + nav["moment_y"] ** 2)
        ** 0.5
    ) / thickness**2 / 1e6

    # Timoshenko Table 8 check on a square plate (independent of the patch case)
    square = solve_rect_panel(
        40,
        40,
        1.0,
        1.0,
        young=young,
        poisson=poisson,
        thickness=thickness,
        load=p_ref,
    )
    sq_peak = square.stress_at(0.5, 0.5)
    m_coef = sq_peak["moment_x_Nm_per_m"] / (p_ref * 1.0**2)
    sq_w = float(deflection_at(square, torch.tensor([0.5]), torch.tensor([0.5]))[0])

    return {
        "case": "JOUR-ICE-STRUCT design point, uniform full-breadth patch",
        "design_point": {
            "l_m": a,
            "s_m": b,
            "t_m": thickness,
            "E_Pa": young,
            "nu": poisson,
            "lambda_c_over_l": lambda_c_over_l,
            "patch_m": [c, b],
            "patch_area_m2": c * b,
            "p_ref_MPa": p_ref / 1e6,
            "total_force_N": p_ref * c * b,
        },
        "fem": {
            "mesh": [nx, ny],
            "sigma_vm_MPa": peak["sigma_vm_MPa"],
            "sigma_Mx_MPa": peak["sigma_Mx_MPa"],
            "moment_x_Nm_per_m": peak["moment_x_Nm_per_m"],
            "sampled_at_m": peak["at_m"],
            "projection_force_error_rel": info["force_error_rel"],
        },
        "navier_reference": {
            "sigma_vm_MPa": sig_navier_vm,
            "sigma_Mx_MPa": sig_navier_mx,
            "moment_x_Nm_per_m": nav["moment_x"],
            "force_N": nav["total_force"],
            "terms": nav["terms"],
        },
        "baseline_panel_patch_load_results": {
            "sigma_plate_MPa": 73.37101604723352,
            "sigma_plate_Mx_MPa": 78.66760309419584,
            "source": "work/m20036/papers/jour-ice-struct/data/panel_patch_load_results.json"
            " :: plate_vs_strip[lambda_c_over_l=0.1, full_breadth]",
        },
        "errors_pct": {
            "fem_vs_navier_sigma_Mx": 100.0 * (peak["sigma_Mx_MPa"] / sig_navier_mx - 1.0),
            "fem_vs_navier_sigma_vm": 100.0 * (peak["sigma_vm_MPa"] / sig_navier_vm - 1.0),
            "fem_vs_baseline_sigma_Mx": 100.0
            * (peak["sigma_Mx_MPa"] / 78.66760309419584 - 1.0),
            "fem_vs_baseline_sigma_vm": 100.0
            * (peak["sigma_vm_MPa"] / 73.37101604723352 - 1.0),
        },
        "timoshenko_table8": {
            "M_coef_got": m_coef,
            "M_coef_ref": 0.0479,
            "M_err_pct": 100.0 * (m_coef / 0.0479 - 1.0),
            "M_err_pct_vs_exact_series": 100.0 * (m_coef / 0.0478864 - 1.0),
            "w_coef_got": sq_w * square.young * square.thickness**3
            / (12.0 * (1.0 - square.poisson**2)) / (p_ref * 1.0**4),
            "w_coef_ref": 0.00406,
            "mesh": [40, 40],
        },
    }


def nonuniformity_scan(
    *,
    total_force: float = 4.0e4,
    nx: int = 40,
    ny: int = 35,
    grid: int = 97,
    panel: tuple[float, float] = (DESIGN_POINT["l"], DESIGN_POINT["s"]),
    thickness: float = DESIGN_POINT["t"],
    young: float = DESIGN_POINT["E"],
    poisson: float = DESIGN_POINT["nu"],
    ceiling: float = 2.0e6,
    configurations: list[dict] | None = None,
) -> dict:
    """Peak panel stress: non-uniform CZM patch vs uniform patch, per configuration.

    ``total_force = 40 kN`` over a ~0.2 m footprint is a mean pressure of ~1 MPa,
    i.e. the JOUR-ICE-STRUCT design point; every configuration is compared with a
    uniform patch of the same total force and the same footprint, so the delta is
    attributable to the pressure non-uniformity alone.
    """
    law = default_law()
    a, b = panel
    configs = default_configurations() if configurations is None else configurations
    rows: list[dict] = []
    for cfg in configs:
        edge = dict(cfg["edge"])
        centre = (
            (0.5 * a + cfg["offset"][0], 0.5 * b + cfg["offset"][1])
            if cfg.get("offset")
            else None
        )
        if cfg.get("coupled", False):
            patch, sol, coup = coupled_patch_solve(
                nx=nx,
                ny=ny,
                panel=panel,
                thickness=thickness,
                young=young,
                poisson=poisson,
                law=law,
                ceiling=ceiling,
                edge=edge,
                total_force=total_force,
                centre=centre,
                grid=grid,
            )
            projection_error = coup["history"][-1]["force_projection_error_rel"]
        else:
            patch = czm_contact_patch(
                law=law,
                ceiling=ceiling,
                edge=edge,
                total_force=total_force,
                panel=panel,
                centre=centre,
                grid=grid,
            )
            sol, info = _solve_with_patch(
                patch,
                nx=nx,
                ny=ny,
                panel=panel,
                thickness=thickness,
                young=young,
                poisson=poisson,
            )
            projection_error = info["force_error_rel"]
            coup = {
                "sweeps": 1,
                "converged": True,
                "tol": 0.0,
                "history": [
                    {
                        "sweep": 0,
                        "approach_m": patch.approach,
                        "peak_pressure_MPa": patch.peak_pressure / 1e6,
                        "contact_area_m2": patch.contact_area,
                        "force_projection_error_rel": projection_error,
                        "pressure_change_rel": float("nan"),
                    }
                ],
            }

        # uniform reference: same force, same footprint, centred on the patch centroid
        xc, yc = patch.centroid
        half_x = 0.5 * float(patch.x[-1] - patch.x[0])
        half_y = 0.5 * float(patch.y[-1] - patch.y[0])
        uni = uniform_patch_pressure(
            total_force=patch.total_force,
            centre=(xc, yc),
            half_x=half_x,
            half_y=half_y,
            panel=panel,
            grid=grid,
        )
        sol_uni, info_uni = _solve_with_patch(
            uni,
            nx=nx,
            ny=ny,
            panel=panel,
            thickness=thickness,
            young=young,
            poisson=poisson,
        )

        peak_np = sol.peak_stress()
        peak_uni = sol_uni.peak_stress()
        # independent series check at the respective FEM peak points
        nav_np = navier_rect_moments(
            patch,
            a,
            b,
            young=young,
            poisson=poisson,
            thickness=thickness,
            x=peak_np["peak_sigma_Mx_at_m"][0],
            y=peak_np["peak_sigma_Mx_at_m"][1],
        )
        nav_uni = navier_rect_moments(
            uni,
            a,
            b,
            young=young,
            poisson=poisson,
            thickness=thickness,
            x=peak_uni["peak_sigma_Mx_at_m"][0],
            y=peak_uni["peak_sigma_Mx_at_m"][1],
        )
        nav_np_mx = 6.0 * abs(nav_np["moment_x"]) / thickness**2 / 1e6
        nav_uni_mx = 6.0 * abs(nav_uni["moment_x"]) / thickness**2 / 1e6

        rows.append(
            {
                "name": cfg["name"],
                "note": cfg.get("note", ""),
                "coupled": bool(cfg.get("coupled", False)),
                "edge": edge,
                "offset_m": list(cfg.get("offset", (0.0, 0.0))),
                "total_force_N": patch.total_force,
                "contact_area_m2": patch.contact_area,
                "footprint_m": [2 * half_x, 2 * half_y],
                "peak_pressure_MPa": patch.peak_pressure / 1e6,
                "mean_pressure_MPa": patch.total_force / patch.contact_area / 1e6,
                "pressure_peak_over_mean": patch.peak_pressure
                / (patch.total_force / patch.contact_area),
                "force_residual": patch.residual,
                "force_projection_error_rel": projection_error,
                "centroid_m": [xc, yc],
                "approach_m": patch.approach,
                "coupling": {
                    "sweeps": coup["sweeps"],
                    "converged": coup["converged"],
                    "history": coup["history"],
                },
                "nonuniform_patch": {
                    "sigma_vm_MPa": peak_np["sigma_vm_MPa"],
                    "sigma_Mx_MPa": peak_np["sigma_Mx_MPa"],
                    "peak_at_m": peak_np["peak_sigma_Mx_at_m"],
                    "navier_sigma_Mx_MPa": nav_np_mx,
                    "fem_vs_navier_Mx_err_pct": 100.0
                    * (peak_np["sigma_Mx_MPa"] / nav_np_mx - 1.0),
                },
                "uniform_reference_patch": {
                    "sigma_vm_MPa": peak_uni["sigma_vm_MPa"],
                    "sigma_Mx_MPa": peak_uni["sigma_Mx_MPa"],
                    "peak_at_m": peak_uni["peak_sigma_Mx_at_m"],
                    "navier_sigma_Mx_MPa": nav_uni_mx,
                    "fem_vs_navier_Mx_err_pct": 100.0
                    * (peak_uni["sigma_Mx_MPa"] / nav_uni_mx - 1.0),
                    "pressure_MPa": uni.peak_pressure / 1e6,
                    "force_projection_error_rel": info_uni["force_error_rel"],
                },
                "delta_nonuniform_over_uniform": {
                    "sigma_vm": peak_np["sigma_vm_MPa"] / peak_uni["sigma_vm_MPa"],
                    "sigma_Mx": peak_np["sigma_Mx_MPa"] / peak_uni["sigma_Mx_MPa"],
                    "sigma_vm_pct": 100.0
                    * (peak_np["sigma_vm_MPa"] / peak_uni["sigma_vm_MPa"] - 1.0),
                    "sigma_Mx_pct": 100.0
                    * (peak_np["sigma_Mx_MPa"] / peak_uni["sigma_Mx_MPa"] - 1.0),
                },
            }
        )
    ratios = [r["delta_nonuniform_over_uniform"]["sigma_Mx"] for r in rows]
    return {
        "case": "ice panel patch load from CZM contact: non-uniformity scan",
        "setting": {
            "panel_m": [a, b],
            "thickness_m": thickness,
            "E_Pa": young,
            "nu": poisson,
            "mesh": [nx, ny],
            "contact_grid": grid,
            "total_force_N": total_force,
            "ceiling_MPa": ceiling / 1e6,
            "interface_law": {
                "stiffness_Pa_per_m": law.stiffness,
                "peak_traction_MPa": law.peak_traction / 1e6,
                "fracture_energy_J_per_m2": law.fracture_energy,
            },
            "uniform_reference": "same total force, same footprint, centred on the patch centroid",
        },
        "configurations": rows,
        "summary": {
            "n_configurations": len(rows),
            "sigma_Mx_ratio_min": min(ratios),
            "sigma_Mx_ratio_max": max(ratios),
            "all_couplings_converged": all(
                r["coupling"]["converged"] for r in rows
            ),
            "max_force_projection_error_rel": max(
                r["force_projection_error_rel"] for r in rows
            ),
            "max_fem_vs_navier_err_pct": max(
                abs(r["nonuniform_patch"]["fem_vs_navier_Mx_err_pct"]) for r in rows
            ),
        },
    }
